import java.io.*;
import java.util.Arrays;

public class Main {
    static int nextInt(DataInputStream in) throws IOException {
        int b = in.read();
        while (b != -1 && (b < '0' || b > '9')) b = in.read();
        int ret = 0;
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return ret;
    }

    //_Minimum number of centers(radius R)to cover all vertices of the tree, classic greedy on rooted tree.
    static int minCenters(int N, int R, int[] order, int[] par, int[] head, int[] nxt, int[] to, int[] unc, int[] cov) {
        final int NEG = Integer.MIN_VALUE / 4;
        int cnt = 0;
        for (int t = N - 1; t >= 0; t--) { // reversed preorder: all children before parent
            int v = order[t];
            int m1 = NEG, m2 = NEG, c1 = 0, cc = 0;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (w == par[v]) continue;
                int a = cov[w] - 1;
                if (a > m1) { m2 = m1; m1 = a; c1 = 1; }
                else if (a == m1) c1++;
                else if (a > m2) m2 = a;
                cc++;
            }
            int covV = (cc == 0) ? -1 : m1; // remaining reach at v from best placed center below
            int uncV = -1;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (w == par[v]) continue;
                if (unc[w] < 0) continue;
                int b = unc[w] + 1;
                int a = cov[w] - 1;
                int others = (a == m1 && c1 == 1) ? m2 : m1; // max coverage from other children
                if (b > others && b > uncV) uncV = b;
            }
            if (covV < 0 && uncV < 0) uncV = 0; // v itself uncovered
            if (uncV == R) { // must place a radar here
                cnt++;
                covV = R;
                uncV = -1;
            }
            unc[v] = uncV;
            cov[v] = covV;
        }
        if (unc[order[0]] >= 0) cnt++; // root: one radar covers all remaining uncovered vertices
        return cnt;
    }

    public static void main(String[] args) throws Exception {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int N = nextInt(in), K = nextInt(in);
        if (N <= 1) { System.out.println(0); return; }
        int M = N - 1;
        int[] head = new int[N + 1];
        Arrays.fill(head, -1);
        int[] nxt = new int[2 * M], to = new int[2 * M];
        for (int i = 0; i < M; i++) {
            int a = nextInt(in), b = nextInt(in);
            nxt[2 * i] = head[a]; to[2 * i] = b; head[a] = 2 * i;
            nxt[2 * i + 1] = head[b]; to[2 * i + 1] = a; head[b] = 2 * i + 1;
        }
        // preorder (stack-based, no recursion)
        int[] par = new int[N + 1], order = new int[N], stk = new int[N];
        int top = 0;
        stk[top++] = 1;
        par[1] = 0;
        int idx = 0;
        while (top > 0) {
            int v = stk[--top];
            order[idx++] = v;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                int w = to[e];
                if (w != par[v]) {
                    par[w] = v;
                    stk[top++] = w;
                }
            }
        }
        int[] unc = new int[N + 1], cov = new int[N + 1];
        int lo = -1, hi = N; // f(N) always feasible with 1 center, f(0) needs N centers
        while (hi - lo > 1) {
            int mid = (lo + hi) >>> 1;
            if (minCenters(N, mid, order, par, head, nxt, to, unc, cov) <= K) hi = mid;
            else lo = mid;
        }
        System.out.println(hi);
    }
}
